      <tr><td><input name="item" value="Modified-bitumen flat roof" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="9800" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="8" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="20" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Plaster repair & paint — two rooms" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="3200" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="6" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="12" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Hardwood floor refinish" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="2600" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="10" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="25" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Water heater" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="1450" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="7" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="12" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr>
